        "category": {
            "description": "Category of register entry (NB some registers may have more than one type of entry, so we record at the register entry level, rather than the register level)",
            "type": "string",
            "enum": [
                "Charity-NonProfit",
                "Lobbying",
                "LegalEntity",
                "Other"
            ]
