                    },
                    "convert_stats": {
                        "default": true,
                        "type": "boolean"
                    },
                    "freesurfer_license": {
                        "type": "string"
                    }
                }
            }
        },
        "title": "Invocation manifest for FreeSurfer (v6.0.0): Recon-All"
    }
